solution_1:
题目很善意地提醒了一句：最左端是不会捕食其他生物的生产者，最右端是不会被其他生物捕食的消费者 DAG的计数问题√，我们只需要进行一个DFS就行了。

我们的思路：

记录所有消费者，以消费者作为搜索起点

记录所有生产者，以生产者作为搜索终点

我们可以用一个bool数组对第一条进行标记。

可以用二维动态数组存储一个物种的直接食物，一个物种是生产者等价于存储它的食物的动态数组为空

楼上的老哥用了一个拓补排序_(:зゝ∠)_蒟蒻并不会，所以我们要用一个相对简单的技巧——记忆化——进行优化。

#include<bits/stdc++.h>
using namespace std;
const int mod=80112002;
bool nHst[5050];
//false -> 食物链顶端
vector<int>Eat[5050];
int dp[5050];
int n,m;
int ans;
int dfs(int now){
    if(!Eat[now].size()) return dp[now]=1;
    int res=0;
    for(int i=0;i<Eat[now].size();i++){
        int &nxt=Eat[now][i];
        res+=dp[nxt]?dp[nxt]:dfs(nxt);
        res%=mod;
    }
    return dp[now]=res;
}
int main(){
    cin>>n>>m;
    int x,y;
    while(m--){
        scanf("%d%d",&x,&y);
        //y吃x
        Eat[y].push_back(x);
        nHst[x]=true;
    }
    for(int i=1;i<=n;i++) if(!nHst[i]) 
        ans=(ans+dfs(i))%mod;
    cout<<ans;    
    return 0;
}

